import { Button, Color, Graphics, Label, Mask, Node, Sprite, SpriteFrame, Tween, UITransform, UIOpacity, Vec3, tween } from 'cc';
import { node, text } from './GrayUI';

/** Stable scene property order. The binding tool reads UUIDs generated by this Creator. */
export const ART_KEYS = [
    'temple_background', 'character_meditate', 'cushion_straw', 'wooden_fish', 'mallet', 'cushion_red',
    'table_low', 'incense_burner', 'incense_unlit_group', 'incense_lit_group', 'candle_holder', 'flame', 'wind_bell',
    'title_plate', 'toolbar_plate', 'status_plate', 'settings_button', 'button_normal', 'button_selected',
    'lotus_icon', 'icon_incense', 'icon_pray', 'icon_meditate', 'icon_wooden_fish',
] as const;
export type ArtKey = typeof ART_KEYS[number];

export class QuietArt {
    constructor(readonly frames: SpriteFrame[]) {
        ART_KEYS.forEach((key, i) => { if (!frames[i]) throw new Error(`缺少美术 SpriteFrame: ${key}，请运行 validation/bind-art.cjs`); });
    }
    frame(key: ArtKey): SpriteFrame { return this.frames[ART_KEYS.indexOf(key)]; }
    sprite(parent: Node, key: ArtKey, x: number, y: number, width: number, height?: number, anchorX = 0.5, anchorY = 0.5): Node {
        const f = this.frame(key); const size = f.originalSize;
        const n = node(parent, key, x, y, width, height === undefined ? width * size.height / size.width : height);
        n.getComponent(UITransform)!.setAnchorPoint(anchorX, anchorY);
        const s = n.addComponent(Sprite); s.sizeMode = Sprite.SizeMode.CUSTOM; s.trim = false; s.spriteFrame = f;
        // Default Sprite material uses straight alpha SRC_ALPHA / ONE_MINUS_SRC_ALPHA.
        return n;
    }
}

export class ArtNavButton {
    readonly button: Button; private normal: Node; private selected: Node;
    private opacity: UIOpacity; private visual: Node;
    constructor(parent: Node, art: QuietArt, title: string, icon: ArtKey, x: number, action: () => void) {
        const container = node(parent, title, x, 14, 204, 188);
        this.visual = node(container, 'Visual', 0, 0, 204, 188);
        // The two frames share exactly the same rectangle; no resizing of the hit container.
        this.normal = art.sprite(this.visual, 'button_normal', 0, 0, 204, 188);
        this.selected = art.sprite(this.visual, 'button_selected', 0, 0, 204, 188);
        this.selected.active = false;
        const image = art.sprite(this.visual, icon, 0, 30, 106); image.name = 'Icon';
        const transform = image.getComponent(UITransform)!;
        if (transform.height > 104) { const k = 104 / transform.height; image.setScale(k, k, 1); }
        const caption = text(this.visual, title, 0, -44, 28, 180, 38);
        caption.node.name = 'Caption'; caption.isBold = true; caption.lineHeight = 34;
        caption.overflow = Label.Overflow.SHRINK; caption.enableWrapText = false;
        this.opacity = this.visual.addComponent(UIOpacity);
        this.button = container.addComponent(Button);
        container.on(Button.EventType.CLICK, () => { if (this.button.interactable) action(); });
        container.on(Node.EventType.TOUCH_START, () => {
            if (!this.button.interactable) return;
            Tween.stopAllByTarget(this.visual); this.visual.setScale(0.97, 0.97, 1);
        });
        const release = () => { Tween.stopAllByTarget(this.visual); tween(this.visual).to(0.12, { scale: Vec3.ONE }, { easing: 'sineOut' }).start(); };
        container.on(Node.EventType.TOUCH_END, release); container.on(Node.EventType.TOUCH_CANCEL, release);
    }
    setState(enabled: boolean, selected: boolean): void {
        this.button.interactable = enabled; this.normal.active = !selected; this.selected.active = selected;
        this.opacity.opacity = enabled ? 255 : 145;
        // Restore only when disabling, so a refresh cannot stack a feedback tween.
        if (!enabled) { Tween.stopAllByTarget(this.visual); this.visual.setScale(1, 1, 1); }
    }
    stop(): void { Tween.stopAllByTarget(this.visual); }
}

/** Burner and bundle are independent. Only the bundle is clipped, never the smoke/character. */
export class ArtIncense {
    readonly root: Node; readonly clip: Node; readonly group: Node; readonly mouthY: number;
    constructor(parent: Node, readonly art: QuietArt, x: number, y: number, width: number) {
        this.root = node(parent, 'IncenseRoot', x, y);
        const burner = art.sprite(this.root, 'incense_burner', 0, 0, width); burner.name = 'Burner';
        // Pixel measurement on the actual 338x239 burner: front inner lip at source y=82.
        this.mouthY = (239 / 2 - 82) * width / 338;
        this.clip = node(this.root, '炉口以上_香杆局部Mask', 0, this.mouthY, width, 500);
        this.clip.getComponent(UITransform)!.setAnchorPoint(0.5, 0);
        this.clip.addComponent(Mask).type = Mask.Type.GRAPHICS_RECT;
        this.group = ArtIncense.bundle(this.clip, art); this.group.setPosition(0, -18);
    }
    static bundle(parent: Node, art: QuietArt): Node {
        const root = node(parent, 'IncenseGroup');
        const height = 142;
        for (const key of ['incense_unlit_group', 'incense_lit_group'] as const) {
            const size = art.frame(key).originalSize;
            const n = art.sprite(root, key, 0, 0, height * size.width / size.height, height, 0.5, 0);
            n.active = key === 'incense_unlit_group';
        }
        return root;
    }
    static lit(group: Node, value: boolean): void {
        group.getChildByName('incense_unlit_group')!.active = !value;
        group.getChildByName('incense_lit_group')!.active = value;
    }
}

/** Static props. The motion pack owns the visible mallet and all contact timing in fish mode. */
export class ArtWoodfish {
    readonly root: Node; readonly fish: Node; readonly pivot: Node; readonly hit: Button;
    readonly ring: Graphics; readonly focus: UIOpacity;
    private readonly rest = -20; private readonly contact = 55;
    constructor(parent: Node, art: QuietArt, onTap: () => void) {
        this.root = node(parent, 'WoodenFishRoot', 315, -300);
        // Source contact points: fish base=(168,240), pad seat=(156.5,48), pad base=(156.5,132),
        // tabletop center=(184.5,69). Align actual support surfaces, not canvas rectangles.
        const supportX = (168 - 317 / 2) * 205 / 317;
        const fishBaseY = 90 + (263 / 2 - 240) * 205 / 317;
        const padY = fishBaseY - (162 / 2 - 48) * 220 / 313;
        const padBaseY = padY + (162 / 2 - 132) * 220 / 313;
        const tableWidth = 240;
        const tableY = padBaseY - (222 / 2 - 69) * tableWidth / 369;
        // Position the complete furniture group in Courtyard; keep all support surfaces centered.
        art.sprite(this.root, 'table_low', supportX, tableY, tableWidth).name = 'LowTable';
        art.sprite(this.root, 'cushion_red', supportX, padY, 220).name = 'RedCushion';
        this.fish = art.sprite(this.root, 'wooden_fish', 0, 90, 205); this.fish.name = 'WoodenFish';
        const halo = node(this.root, '点击提示', 0, 87); this.focus = halo.addComponent(UIOpacity);
        const g = halo.addComponent(Graphics); g.strokeColor = new Color(234, 214, 158, 150); g.lineWidth = 3;
        g.ellipse(0, 0, 112, 90); g.stroke(); this.focus.opacity = 0;
        // Opaque edge samples: mallet grip=(28,233), head=(139,116); fish top=(186,34).
        const height = 180;
        const k = height / 256, dx = (139 - 28) * k, dy = (233 - 116) * k;
        const radians = this.contact * Math.PI / 180;
        const contactX = (186 - 317 / 2) * 205 / 317;
        const contactY = 90 + (263 / 2 - 34) * 205 / 317;
        this.pivot = node(this.root, 'MalletPivot_握柄轴', contactX - dx * Math.cos(radians) + dy * Math.sin(radians), contactY - dx * Math.sin(radians) - dy * Math.cos(radians));
        art.sprite(this.pivot, 'mallet', 0, 0, 202 * k, height, 28 / 202, 1 - 233 / 256).name = 'Mallet';
        node(this.pivot, 'ContactPoint', dx, dy); this.pivot.angle = this.rest;
        this.hit = node(this.root, '木鱼点击区', 0, 70, 260, 220).addComponent(Button);
        this.hit.node.on(Node.EventType.TOUCH_START, onTap);
        this.ring = node(this.root, '敲击涟漪', 0, 90).addComponent(Graphics);
    }
    stop(): void {
        this.pivot.angle = this.rest;
        Tween.stopAllByTarget(this.fish); this.fish.setScale(1, 1, 1);
        this.fish.setPosition(0, 90);
    }
}
